    expr = "{'id': input_data['id'], 'name': input_data['name']}"
    data = {'id': 1, 'name': 'Alice', 'age': 30}
    result = transform_step_data(expr, data)
    assert result == {'id': 1, 'name': 'Alice'}


def test_arithmetic_operations():
    expr = "{'total': input_data['price'] * input_data['quantity']}"
    data = {'price': 10, 'quantity': 5}
    result = transform_step_data(expr, data)
